{
  "domain": "maenifold.workflow",
  "commands": [
    {
      "name": "DeleteWorkflowAsset",
      "description": "Deletes one workflow asset by name when no running pipeline references it.",
      "safety_class": "destructive"
    },
    {
      "name": "Pipeline",
      "description": "Creates and manages pipeline sessions composed of DAG nodes.",
      "safety_class": "orchestration"
    },
    {
      "name": "SaveWorkflowAsset",
      "description": "Saves (creates or overwrites) a workflow asset by id.",
      "safety_class": "mutate"
    },
    {
      "name": "Workflow",
      "description": "Runs structured workflows with optional nested submachines.",
      "safety_class": "orchestration"
    }
  ]
}
